#pragma once
#include "commitment_ref.hpp"
#include "resident/checkpoint/codec_visitor.hpp"
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include <type_traits>
namespace hanmo::resident::commitment_codec {
template<class A>Status terms(A&a,TermsRevisionRef&v){if(!a.status().ok)return a.status();bool retained=false;if constexpr(std::is_same_v<std::decay_t<A>,CodecVisitor>)retained=false;StableId kind;if(!a.reading()&&!retained)kind=std::holds_alternative<SourceTermsKey>(v)?"source_terms_key":std::holds_alternative<SourceFactTerms>(v)?"source_fact_terms":"revision";if(!retained)a.field("kind",kind);if(!a.status().ok)return a.status();if(a.reading()){if(kind=="source_terms_key"){if(!prepare_checkpoint_default_values<SourceTermsKey>(a).ok)return a.status();v=SourceTermsKey{};}else if(kind=="source_fact_terms"){if(!prepare_checkpoint_default_values<SourceFactTerms>(a).ok)return a.status();v=SourceFactTerms{};}else if(kind=="revision"){if(!prepare_checkpoint_default_values<Revision>(a).ok)return a.status();v=Revision{};}else return a.reject("UnsupportedTermsRevisionKind");}std::visit([&](auto&x){using T=std::decay_t<decltype(x)>;if constexpr(std::is_same_v<T,SourceTermsKey>)a.field("key",x.key);else if constexpr(std::is_same_v<T,Revision>)a.field("revision",x.revision);else a.object("source",[&](auto&c){c.field("domain",x.source.domain);c.field("kind",x.source.kind);return c.field("id",x.source.id);});},v);if(a.status().ok&&!retained){auto valid=validate_terms_revision(v);if(!valid.ok)return a.reject(valid.error.original.code);}return a.status();}
template<class A>Status commitment(A&a,CommitmentRef&v){a.field("domain",v.domain);a.field("kind",v.kind);a.field("id",v.id);a.object("terms_revision",[&](auto&c){return terms(c,v.terms_revision);});bool retained=false;if constexpr(std::is_same_v<std::decay_t<A>,CodecVisitor>)retained=false;if(a.status().ok&&!retained){auto valid=validate_commitment_ref(v);if(!valid.ok)return a.reject(valid.error.original.code);}return a.status();}
}
